param([Parameter(Mandatory)][string]$BuildDirectory,[Parameter(Mandatory)][ValidateSet('Separate','RdataIntoText')][string]$SectionLayout)
$ErrorActionPreference='Stop'
. "$PSScriptRoot\lib\pe-image.ps1"
function Sections($p){$h=[BitConverter]::ToInt32($p.Bytes,60);$table=$h+24+[BitConverter]::ToUInt16($p.Bytes,$h+20);for($i=0;$i -lt $p.Sections.Count;$i++){$s=$table+40*$i;[pscustomobject]@{Name=[Text.Encoding]::ASCII.GetString($p.Bytes,$s,8).Trim([char]0);RVA=[long][BitConverter]::ToUInt32($p.Bytes,$s+12);VirtualSize=[long][BitConverter]::ToUInt32($p.Bytes,$s+8);RawSize=[long][BitConverter]::ToUInt32($p.Bytes,$s+16);RawOffset=[long][BitConverter]::ToUInt32($p.Bytes,$s+20);Flags=('{0:X8}' -f [BitConverter]::ToUInt32($p.Bytes,$s+36))}}}
$a=Open-PE "$PSScriptRoot\..\original\fsx.exe";$b=Open-PE "$BuildDirectory\fsx.exe";$old=@(Sections $a|Where-Object Name -CNE '.rsrc');$new=@(Sections $b)
$expected=if($SectionLayout -eq 'Separate'){@('.text','.rdata','.data')}else{@('.text','.data')}
if(($new.Name|ConvertTo-Json -Compress) -cne ($expected|ConvertTo-Json -Compress)){throw 'Actual sections differ from requested section layout'}
foreach($s in $new){$flags=switch($s.Name){'.text'{'60000020'}'.rdata'{'40000040'}'.data'{'C0000040'}};if($s.Flags -cne $flags){throw 'Section flags differ from established access/type flags'}}
$rows=foreach($x in $old){$y=$new|Where-Object Name -CEQ $x.Name;[pscustomobject]@{Name=$x.Name;Original=$x;Rebuilt=$y;RvaMatches=($x.RVA -eq $y.RVA);RawSizeMatches=($x.RawSize -eq $y.RawSize);RawOffsetMatches=($x.RawOffset -eq $y.RawOffset);FlagsMatch=($x.Flags -ceq $y.Flags);VirtualSizeDelta=$y.VirtualSize-$x.VirtualSize}}
[pscustomobject]@{Mode=$SectionLayout;ActualLayoutVerified=$true;OriginalImageBase=('{0:X8}' -f $a.Base);RebuiltImageBase=('{0:X8}' -f $b.Base);OriginalNonResourceSections=$old.Name;RebuiltSections=$new.Name;NonResourceSectionNamesAndOrderMatch=(($old.Name|ConvertTo-Json -Compress) -ceq ($new.Name|ConvertTo-Json -Compress));Sections=@($rows);Scope='Requested section topology/access flags enforced. Original non-resource section RVA/raw-size/raw-offset/virtual-size differences reported separately; resource payload, contents, code/import ordering and whole image equality not certified.'}|ConvertTo-Json -Depth 7
